package gsurideshare_backend.controller;
import gsurideshare_backend.model.*; import gsurideshare_backend.repository.*; import gsurideshare_backend.service.CurrentUser; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.HttpStatus; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.*; import java.math.BigDecimal; import java.util.*;
@RestController @RequestMapping("/api/v1/rides") public class RideController {
 public record Create(UUID vehicleId,@NotBlank String originAddress,Double originLat,Double originLng,@NotBlank String destinationAddress,Double destinationLat,Double destinationLng,@NotNull @Future Instant departureTime,@Min(1) @Max(8) int totalSeats,@NotNull @DecimalMin("0.00") BigDecimal pricePerSeat,@Size(max=500) String notes){}
 public record Ask(@Min(1) @Max(8) int seatsRequested,String pickupAddress,Double pickupLat,Double pickupLng,@Size(max=500) String message){}
 public record View(UUID id,UUID driverId,String driverName,UUID vehicleId,String originAddress,String destinationAddress,Instant departureTime,int totalSeats,int availableSeats,BigDecimal pricePerSeat,String notes,String status){}
 public record RequestView(UUID id,UUID rideId,UUID passengerId,String passengerName,int seatsRequested,String pickupAddress,String message,String status){}
 private final RideRepository rides;private final VehicleRepository vehicles;private final RideRequestRepository requests;private final CurrentUser current;
 public RideController(RideRepository r,VehicleRepository v,RideRequestRepository q,CurrentUser c){rides=r;vehicles=v;requests=q;current=c;}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) public View create(@Valid @RequestBody Create x){User u=current.get();if(u.getRole()!=Role.DRIVER)throw new IllegalStateException("Only drivers can post rides");Ride r=new Ride();r.setDriver(u);
 if(x.vehicleId()!=null){Vehicle v=vehicles.findById(x.vehicleId()).orElseThrow(()->new NoSuchElementException("Vehicle not found"));if(!v.getOwner().getId().equals(u.getId()))throw new IllegalArgumentException("Vehicle is not yours");if(x.totalSeats()>v.getSeatCapacity())throw new IllegalArgumentException("Seats exceed vehicle capacity");r.setVehicle(v);}
 r.setOriginAddress(x.originAddress());r.setOriginLat(x.originLat());r.setOriginLng(x.originLng());r.setDestinationAddress(x.destinationAddress());r.setDestinationLat(x.destinationLat());r.setDestinationLng(x.destinationLng());r.setDepartureTime(x.departureTime());r.setTotalSeats(x.totalSeats());r.setAvailableSeats(x.totalSeats());r.setPricePerSeat(x.pricePerSeat());r.setNotes(x.notes());r.setStatus(RideStatus.OPEN);return view(rides.save(r));}
 @GetMapping public List<View> search(@RequestParam(required=false) String origin,@RequestParam(required=false) String destination,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate date,@RequestParam(defaultValue="1") int seats){if(seats<1)throw new IllegalArgumentException("seats must be positive");Instant from=date==null?Instant.now():date.atStartOfDay(ZoneOffset.UTC).toInstant();Instant to=date==null?null:date.plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();return rides.search(clean(origin),clean(destination),from,to,seats).stream().map(RideController::view).toList();}
 @GetMapping("/{id}") public View get(@PathVariable UUID id){return view(findRide(id));}
 @PostMapping("/{id}/cancel") @Transactional public View cancel(@PathVariable UUID id){Ride r=findRide(id);owner(r);if(r.getStatus()==RideStatus.COMPLETED)throw new IllegalStateException("Ride already completed");r.setStatus(RideStatus.CANCELLED);requests.findByRideId(id).stream().filter(q->q.getStatus()==RequestStatus.PENDING||q.getStatus()==RequestStatus.ACCEPTED).forEach(q->q.setStatus(RequestStatus.CANCELLED));return view(rides.save(r));}
 @PostMapping("/{id}/complete") @Transactional public View complete(@PathVariable UUID id){Ride r=findRide(id);owner(r);if(r.getStatus()==RideStatus.CANCELLED)throw new IllegalStateException("Ride cancelled");r.setStatus(RideStatus.COMPLETED);requests.findByRideId(id).stream().filter(q->q.getStatus()==RequestStatus.ACCEPTED).forEach(q->q.setStatus(RequestStatus.COMPLETED));return view(rides.save(r));}
 @PostMapping("/{id}/requests") @ResponseStatus(HttpStatus.CREATED) @Transactional public RequestView request(@PathVariable UUID id,@Valid @RequestBody Ask x){User u=current.get();Ride r=findRide(id);if(r.getDriver().getId().equals(u.getId()))throw new IllegalArgumentException("Cannot request your own ride");if(r.getStatus()!=RideStatus.OPEN||r.getDepartureTime().isBefore(Instant.now()))throw new IllegalStateException("Ride is not open");if(x.seatsRequested()>r.getAvailableSeats())throw new IllegalArgumentException("Not enough seats");if(requests.existsByRideIdAndPassengerId(id,u.getId()))throw new IllegalStateException("Already requested this ride");RideRequest q=new RideRequest();q.setRide(r);q.setPassenger(u);q.setSeatsRequested(x.seatsRequested());q.setPickupAddress(x.pickupAddress());q.setPickupLat(x.pickupLat());q.setPickupLng(x.pickupLng());q.setMessage(x.message());q.setStatus(RequestStatus.PENDING);return requestView(requests.save(q));}
 @GetMapping("/{id}/requests") public List<RequestView> listRequests(@PathVariable UUID id){Ride r=findRide(id);owner(r);return requests.findByRideId(id).stream().map(RideController::requestView).toList();}
 Ride findRide(UUID id){return rides.findById(id).orElseThrow(()->new NoSuchElementException("Ride not found"));}void owner(Ride r){if(!r.getDriver().getId().equals(current.get().getId()))throw new IllegalArgumentException("Only the ride driver can do that");}
 static String clean(String s){return s==null||s.isBlank()?null:s.trim();}
 static View view(Ride r){return new View(r.getId(),r.getDriver().getId(),r.getDriver().getFirstName()+" "+r.getDriver().getLastName(),r.getVehicle()==null?null:r.getVehicle().getId(),r.getOriginAddress(),r.getDestinationAddress(),r.getDepartureTime(),r.getTotalSeats(),r.getAvailableSeats(),r.getPricePerSeat(),r.getNotes(),r.getStatus().name());}
 static RequestView requestView(RideRequest q){return new RequestView(q.getId(),q.getRide().getId(),q.getPassenger().getId(),q.getPassenger().getFirstName()+" "+q.getPassenger().getLastName(),q.getSeatsRequested(),q.getPickupAddress(),q.getMessage(),q.getStatus().name());}
}
